"""LangGraph repair loop: run -> (rules) -> diagnose -> propose -> apply -> run ...

Only the model-facing and decision logic lives here; container work is done by `box`
(see run.Box). The neatlogs handler is attached by the caller at graph invoke, so the nodes
below create no spans of their own.
"""
import json
import re
import time
from typing import TypedDict

from langchain_core.messages import AIMessage, HumanMessage, SystemMessage
from langchain_core.runnables import RunnableConfig
from langgraph.graph import END, START, StateGraph

from resurgo.gateway import MAX_REQUEST_BYTES, ModelLimited, ModelUnavailable
from resurgo.rules import LOCKFILES, apply_rules

MAX_ATTEMPTS = 4          # fix attempts per repo, a rule candidate counts as one
CONFIG_NAMES = {".nvmrc", ".node-version", ".npmrc", ".yarnrc", ".yarnrc.yml",
                "pnpm-workspace.yaml", ".tool-versions", "foundry.toml", "rust-toolchain",
                "rust-toolchain.toml", ".env.example"}
PACKAGE_JSON_KEYS = {"packageManager", "engines", "volta", "pnpm", "overrides", "resolutions",
                     "devEngines"}
LOCKFILE_NAMES = {n for n, _ in LOCKFILES} | {"Cargo.lock"}
UNFIXABLE_STEPS = {"toolchain"}
GAP_STEPS = {"test", "serve"}      # a gap is accepted only here: install and build have passed
FOUNDRY_FILTER = re.compile(r"^\s*(no_match_test|no_match_contract|no_match_path|match_test|"
                            r"match_contract|match_path)\s*=\s*(.*?)\s*$", re.M)
TEST_FILE = re.compile(r"(^|/)(tests?/|[^/]*\.t\.sol$|[^/]*\.(test|spec)\.[^/]+$)")
MANIFEST_BYTES = 12_000
GRAPH_STEPS = {"build", "test", "serve"}
ANSI = re.compile(r"\x1b\[[0-9;]*[A-Za-z]")
ERROR_WORDS = re.compile(r"error|fail|cannot|can't|timed out|timeout|exception|not found|denied|"
                         r"unexpected|missing|invalid", re.I)
ERROR_NOISE = re.compile(r"ELIFECYCLE|Command failed|exit code|exited with|ERR_PNPM_RECURSIVE|"
                         r"npm (ERR|error) (code|path|A complete)", re.I)

SYSTEM = """You repair a project (Node.js, Foundry or Rust) that fails on a fresh machine. \
Diagnose the failing step (install, build, test, or serve: start the server and GET /) from \
the command, exit code and output, then reply with ONE JSON object and nothing else:
{"kind": "config" | "code", "files": [{"path": "<path relative to the repo root>", \
"content": "<complete new file content>"}], "rationale": "<why this fixes it>", \
"confidence": <number from 0 to 1>}
kind "config": only version pins and tool settings: .nvmrc, .node-version, .npmrc, .yarnrc, \
.yarnrc.yml, pnpm-workspace.yaml, foundry.toml, rust-toolchain(.toml), .env.example, and in \
package.json only the packageManager, engines, volta, \
pnpm (for example onlyBuiltDependencies), overrides, resolutions and devEngines fields. Give \
complete file contents; keep every other package.json field unchanged. To regenerate a lockfile, \
list it (or Cargo.lock) with content "". These are applied and re-run.
kind "code": any change to source, tests, scripts, dependencies or build setup (for example \
turbo.json), including package.json fields other than those above. A code fix is applied in an \
isolated sandbox only to verify that it works, then held for the owner's approval; it is never \
merged on its own. Prefer a config fix when one exists. Never make a step pass by removing, \
skipping or weakening a test, a build or a check: edits that add test filters, delete test files \
or change the package.json test script are rejected.
kind "gap": when the failing step is test or serve and it fails only because it needs an \
external service or credential a fresh machine cannot have (for example an Ethereum RPC \
endpoint), reply {"kind": "gap", "reason": "<the service or credential the step needs>", \
"rationale": "<why>", "confidence": <0 to 1>} and change nothing. Never for install or build."""


class State(TypedDict, total=False):
    failure: dict
    attempts: list
    rules_tried: bool
    rule_applied: bool
    rules_fired: list
    system: str
    user: str
    raw: str
    proposal: dict
    graph_context: dict
    reasked: bool
    status: str
    detail: str


def parse_proposal(raw):
    """(proposal, error). Strict JSON; a leading ```json fence is tolerated."""
    text = raw.strip()
    m = re.match(r"^```(?:json)?\s*(.*?)\s*```$", text, re.S)
    if m:
        text = m.group(1)
    try:
        p = json.loads(text)
    except ValueError as e:
        return None, f"not valid JSON: {e}"
    if not isinstance(p, dict):
        return None, "top level must be a JSON object"
    if p.get("kind") not in ("config", "code", "gap"):
        return None, 'kind must be "config", "code" or "gap"'
    if p["kind"] == "gap":
        reason = p.get("reason")
        if not (isinstance(reason, str) and reason.strip()):
            return None, 'a gap needs a string "reason"'
        p = {**p, "reason": " ".join(reason.split())[:80], "files": []}   # a gap changes nothing
    files = p.get("files")
    if not isinstance(files, list):
        return None, "files must be a list"
    for f in files:
        if not (isinstance(f, dict) and isinstance(f.get("path"), str) and isinstance(f.get("content"), str)):
            return None, 'each file needs a string "path" and a string "content"'
        parts = f["path"].split("/")
        if f["path"].startswith("/") or ".." in parts or parts[0] == ".git" or not f["path"]:
            return None, f"unsafe path {f['path']!r}"
    if not isinstance(p.get("rationale"), str):
        return None, "rationale must be a string"
    c = p.get("confidence")
    if isinstance(c, bool) or not isinstance(c, (int, float)) or not 0 <= c <= 1:
        return None, "confidence must be a number between 0 and 1"
    return p, None


def test_script(pkg):
    scripts = pkg.get("scripts")
    return scripts.get("test") if isinstance(scripts, dict) else None


def proposal_problem(box, proposal):
    """(malformed, weakens, code_reason). `malformed` is why the proposal cannot be applied at all
    (a lockfile with written content, invalid package.json). `weakens` is why it skips or weakens
    tests (a foundry.toml test filter, a deleted test file, a changed package.json test script).
    `code_reason` is why it is a code change although it may be labelled config (a file outside
    CONFIG_NAMES, a non-config package.json key). Each is None when it does not apply."""
    code = weak = None
    # a rename is a deletion plus a written test file; more deletions than that drop tests
    tests = [f for f in proposal["files"] if TEST_FILE.search(f["path"])]
    gone = [f["path"] for f in tests if f["content"] == ""]
    if len(gone) > len(tests) - len(gone):
        weak = f"{gone[0]}: deletes a test file"
    for f in proposal["files"]:
        name = f["path"].rsplit("/", 1)[-1]
        if name in LOCKFILE_NAMES:
            if f["content"] != "":
                return f"{f['path']}: a lockfile can only be regenerated (content \"\")", None, None
        elif name == "package.json":
            old = box.read(f["path"])
            try:
                old, new = json.loads(old or "{}"), json.loads(f["content"])
            except ValueError:
                return f"{f['path']}: not valid JSON", None, None
            if not isinstance(old, dict) or not isinstance(new, dict):
                return f"{f['path']}: must be a JSON object", None, None
            changed = {k for k in old.keys() | new.keys() if old.get(k) != new.get(k)}
            if changed - PACKAGE_JSON_KEYS and not code:
                code = f"{f['path']}: changes {sorted(changed - PACKAGE_JSON_KEYS)}, which is not config"
            if test_script(old) != test_script(new):
                weak = weak or f"{f['path']}: changes the test script"
        else:
            if name == "foundry.toml":
                added = set(FOUNDRY_FILTER.findall(f["content"])) - set(FOUNDRY_FILTER.findall(
                    box.read(f["path"]) or ""))
                if added:
                    weak = weak or f"{f['path']}: adds or changes test filter {sorted(added)[0][0]}"
            if name not in CONFIG_NAMES and not code:
                code = f"{f['path']}: not a config file"
    return None, weak, code


def error_line(out):
    """The most informative line of a step's output: the first line with an error word that is not
    a generic "command failed" wrapper, else the last non-empty line. At most 200 characters."""
    lines = [l for l in (ANSI.sub("", l).strip() for l in out.splitlines()[-200:]) if l]
    pick = next((l for l in lines if ERROR_WORDS.search(l) and not ERROR_NOISE.search(l)), None)
    return (pick or (lines[-1] if lines else ""))[:200]


def build_prompt(box, failure, attempts, graph=None):
    """User message: command, exit code, manifests, history, repository context (`graph`, from
    Box.graph_search) when there is any, then as much output tail as fits under the request limit."""
    parts = [f"Project type: {box.ptype} ({box.why}); image {box.image}",
             f"Failing step: {failure['step']}", f"Command: {failure['command']}",
             f"Exit code: {failure['exit_code']}", f"Environment: {box.versions or 'unknown'}",
             f"Project path in repo: {box.subdir or '.'}"]
    if attempts:
        parts.append("Previous attempts (do not repeat what failed):")
        for a in attempts:
            parts.append(f"- {a['source']} {a['kind']} {a['files']}: {a.get('result')}")
    names = ["package.json", ".nvmrc", ".node-version", ".npmrc", ".yarnrc.yml",
             "pnpm-workspace.yaml", "foundry.toml", "Cargo.toml", "rust-toolchain.toml",
             "rust-toolchain", ".env.example"] + sorted(LOCKFILE_NAMES - {"bun.lockb"})  # binary
    found = box.read_many([p for n in names for p in {box.rel(n), n}])
    seen = set()
    for name in names:
        for path in (box.rel(name), name):
            if path in seen:
                continue
            seen.add(path)
            text = found.get(path)
            if text is None:
                continue
            if name in LOCKFILE_NAMES:
                text = "\n".join(text.splitlines()[:30]) + "\n[lockfile truncated]"
            parts.append(f"--- {path} ---\n{text[:MANIFEST_BYTES]}")
    if graph:
        parts.append("--- Repository context (entire-graph): the code most related to this failure ---\n"
                     + graph["text"])
    head = "\n\n".join(parts) + "\n\n--- output tail ---\n"
    # leave room for a re-ask (the reply plus an error line) inside the same limit
    room = MAX_REQUEST_BYTES - len((SYSTEM + head).encode()) - 8_000
    tail = box.last_out.encode()[-max(room, 0):].decode(errors="ignore")
    return head + tail


def build_graph(box, model, deadline):
    def over_budget():
        return time.monotonic() > deadline

    def applied(state):
        return [a for a in state.get("attempts", []) if a["status"] == "applied"]

    def settle(attempts, result):
        """Record how the last applied attempt turned out once it has been re-run."""
        if attempts and attempts[-1]["status"] == "applied" and attempts[-1].get("result") is None:
            attempts = attempts[:-1] + [{**attempts[-1], "result": result}]
        return attempts

    def run(state):
        if over_budget():
            return {"status": "budget_exhausted", "detail": f"{box.cap_s // 60} minute budget used"}
        failure = box.pipeline()
        attempts = settle(state.get("attempts", []),
                          "passed" if failure is None else f"failed at {failure['step']}")
        if failure is None:
            return {"status": "passed", "failure": {}, "attempts": attempts}
        out = {"failure": failure, "attempts": attempts}
        if failure["step"] in UNFIXABLE_STEPS:
            out.update(status="fail", detail=f"{failure['step']} failed; not a fixable step")
        elif len(applied({"attempts": attempts})) >= MAX_ATTEMPTS:
            out.update(status="budget_exhausted", detail=f"{MAX_ATTEMPTS} fix attempts used")
        return out

    def rules(state):
        failure = state.get("failure") or {}
        install_out = box.last_out if failure.get("step") == "install" else ""
        fired, fixes = apply_rules(box.rule_files(), install_out)
        attempts = list(state.get("attempts", []))
        if fixes:
            paths = box.write({box.rel(n): c for n, c in fixes.items()})
            attempts.append({"source": "rule", "kind": "config", "files": paths,
                             "rationale": "; ".join(f"{r['rule']}: {r['value']} from {r['source']}"
                                                    for r in fired),
                             "confidence": None, "status": "applied", "result": None})
        return {"rules_tried": True, "rule_applied": bool(fixes), "rules_fired": fired,
                "attempts": attempts}

    def ask(messages, config):
        return model.invoke(messages, config).content

    def failed_model(e):
        if isinstance(e, ModelLimited):
            return {"status": "model_limited", "detail": str(e)}
        return {"status": "model_unavailable", "detail": str(e)}

    def diagnose(state, config: RunnableConfig):
        if over_budget():
            return {"status": "budget_exhausted", "detail": f"{box.cap_s // 60} minute budget used"}
        failure, graph = state["failure"], None
        if failure["step"] in GRAPH_STEPS:
            line = error_line(box.last_out)
            if line:
                graph = box.graph_search(f"{failure['step']} fails: {line}")
        user = build_prompt(box, failure, state.get("attempts", []), graph)
        try:
            raw = ask([SystemMessage(SYSTEM), HumanMessage(user)], config)
        except (ModelLimited, ModelUnavailable) as e:
            return failed_model(e)
        meta = {k: v for k, v in graph.items() if k != "text"} if graph else None
        return {"system": SYSTEM, "user": user, "raw": raw, "reasked": False, "graph_context": meta}

    def judge(raw, failure):
        """(proposal, error, weakens): the proposal when it can go on, else why not. `weakens`
        is True when the error is a rejection for skipping or weakening tests."""
        proposal, err = parse_proposal(raw)
        if err:
            return None, err, False
        if proposal["kind"] == "gap":
            step = (failure or {}).get("step")
            if step not in GAP_STEPS:
                return proposal, ("a gap is only accepted when install and build passed and the "
                                  f"failing step is test or serve, not {step}"), False
            return proposal, None, False
        if not proposal["files"]:
            return proposal, None, False       # apply() ends the run: nothing to apply
        malformed, weak, code = proposal_problem(box, proposal)
        if malformed:
            return proposal, malformed, False
        if weak:
            return proposal, f"this skips or weakens tests: {weak}", True
        return {**proposal, "code_reason": code}, None, False

    def propose(state, config: RunnableConfig):
        failure = state.get("failure")
        proposal, err, weak = judge(state["raw"], failure)
        if not err:
            return accept(state, proposal)
        msgs = [SystemMessage(state["system"]), HumanMessage(state["user"]),
                AIMessage(state["raw"][:4000]),
                HumanMessage(f"That reply was rejected: {err}. "
                             "Reply again with only the JSON object.")]
        try:
            raw = ask(msgs, config)
        except (ModelLimited, ModelUnavailable) as e:
            return failed_model(e)
        proposal, err, weak = judge(raw, failure)
        if not err:
            return {**accept(state, {**proposal, "reasked": True}), "raw": raw}
        out = {"status": "broken" if weak else "invalid_proposal", "detail": err, "raw": raw}
        if proposal:     # keep what was rejected in the record
            out["attempts"] = list(state.get("attempts", [])) + [{
                "source": "model", "kind": proposal["kind"],
                "files": [f["path"] for f in proposal["files"]], "rationale": proposal["rationale"],
                "confidence": proposal["confidence"], "status": "rejected", "result": err,
                "files_content": proposal["files"], "graph_context": state.get("graph_context")}]
        return out

    def accept(state, proposal):
        """A gap ends the run here (see Box.accept_gap); anything else goes on to apply."""
        if proposal["kind"] != "gap":
            return {"proposal": proposal}
        step = state["failure"]["step"]
        box.accept_gap = (step, proposal["reason"])
        box.gaps.append(f"needs {proposal['reason']} ({step} step)")
        entry = {"source": "model", "kind": "gap", "files": [], "rationale": proposal["rationale"],
                 "confidence": proposal["confidence"], "status": "accepted",
                 "result": proposal["reason"], "graph_context": state.get("graph_context")}
        return {"status": "passed", "detail": box.gaps[-1],
                "attempts": list(state.get("attempts", [])) + [entry]}

    def apply(state):
        p = state["proposal"]
        attempts = list(state.get("attempts", []))
        entry = {"source": "model", "kind": p["kind"], "files": [f["path"] for f in p["files"]],
                 "rationale": p["rationale"], "confidence": p["confidence"], "result": None,
                 "recovered_from_invalid_json": p.get("reasked", False),
                 "graph_context": state.get("graph_context")}
        code = p.get("code_reason")
        if not p["files"]:
            problem = "proposal has no files"
            entry.update(status="needs_approval", result=problem, files_content=p["files"])
            return {"attempts": attempts + [entry], "status": "fail", "detail": problem}
        if p["kind"] == "code" or code:
            # a code change is applied here only to verify it; the owner approves it later
            entry.update(kind="code", needs_approval=True,
                         approval_reason=code or "proposed as a code change")
        box.write({f["path"]: f["content"] for f in p["files"] if f["content"] != ""})
        box.remove([f["path"] for f in p["files"] if f["content"] == ""])
        entry["status"] = "applied"
        return {"attempts": attempts + [entry]}

    def after_run(state):
        if state.get("status"):
            return END
        return "diagnose" if state.get("rules_tried") else "rules"

    g = StateGraph(State)
    for name, fn in [("run", run), ("rules", rules), ("diagnose", diagnose),
                     ("propose", propose), ("apply", apply)]:
        g.add_node(name, fn)
    g.add_edge(START, "run")
    g.add_conditional_edges("run", after_run, ["rules", "diagnose", END])
    g.add_conditional_edges("rules", lambda s: "run" if s["rule_applied"] else "diagnose",
                            ["run", "diagnose"])
    g.add_conditional_edges("diagnose", lambda s: END if s.get("status") else "propose",
                            ["propose", END])
    g.add_conditional_edges("propose", lambda s: END if s.get("status") else "apply",
                            ["apply", END])
    g.add_conditional_edges("apply", lambda s: END if s.get("status") else "run", ["run", END])
    return g.compile()

"""Turn GitHub App install requests into fresh-clone checks, one build at a time.

Usage: uv run python -m resurgo.worker [--once]

The web API drops $QUEUE_DIR/requests/<installation_id>.json when someone installs the App. This
worker validates the request against the App, plans the checks (public repos, at most 5, at most 3
project paths each), runs them with the sweep's runner and reports progress in
$QUEUE_DIR/status/<installation_id>.json, which the web page shows. Pull requests are opened only
when RESURGO_AUTO_PR=1. A finished installation is re-queued once its status is a week old.
--once works until nothing is left to do, then exits.
"""
import argparse
import json
import os
import subprocess
import sys
import time
from datetime import datetime, timedelta, timezone
from pathlib import Path

import httpx
from dotenv import load_dotenv

from resurgo import __version__
from resurgo.pr import api, app_jwt
from resurgo.run import scrub
from resurgo.sweep import run_one

RUNS = Path("runs")
MANIFESTS = ("package.json", "foundry.toml", "Cargo.toml")
MAX_REPOS, MAX_PATHS = 5, 3
POLL_S = 10
RECHECK_AFTER = timedelta(days=7)
RESULTS = ("runs", "runs_with_gaps", "broken", "unsupported")
OPEN = ("queued", "checking")
WAIT_REASON = "Waiting for the evaluation run to finish. Checks run one at a time."


class GitHubError(Exception):
    pass


def now():
    return datetime.now(timezone.utc).isoformat(timespec="seconds")


def log(line):
    print(line, flush=True)


def call(method, path, token=None, ok_404=False, **kw):
    """pr.api, but every failure is a GitHubError (pr.api exits the process on an error status)."""
    try:
        r = api(method, path, token, **kw)
    except SystemExit as e:
        raise GitHubError(scrub(str(e))) from None
    except httpx.HTTPError as e:
        raise GitHubError(type(e).__name__) from None
    if r.status_code == 404 and not ok_404:
        raise GitHubError(f"GitHub {method} {path.split('?')[0]} returned 404")
    return r


def make_jwt():
    client_id, key = os.environ.get("GITHUB_APP_CLIENT_ID"), os.environ.get("GITHUB_APP_PRIVATE_KEY")
    if not client_id or not key:
        raise GitHubError("GITHUB_APP_CLIENT_ID and GITHUB_APP_PRIVATE_KEY must be set")
    try:
        return app_jwt(client_id, key)
    except SystemExit as e:
        raise GitHubError(str(e)) from None


def choose_paths(tree):
    """Project paths from a git tree listing: the root when it has a manifest, otherwise the
    first-level directories that do (at most MAX_PATHS, by name)."""
    blobs = [e["path"] for e in tree if e.get("type") == "blob"]
    if any(m in blobs for m in MANIFESTS):
        return [""]
    dirs = {p.split("/")[0] for p in blobs if p.count("/") == 1 and p.rsplit("/", 1)[1] in MANIFESTS}
    return sorted(dirs)[:MAX_PATHS]


def find_record(runs_dir, repo, sha, path, version):
    """The newest recorded run of this repo, SHA, path and agent version, or None."""
    for f in sorted(runs_dir.glob("*/result.json"), reverse=True):
        try:
            rec = json.loads(f.read_text())
        except (OSError, ValueError):
            continue
        if (rec.get("repo"), rec.get("sha", "")[:12], rec.get("path", ""), rec.get("agent_version")) \
                == (repo, sha, path, version) and rec.get("result"):
            return rec
    return None


def entry(repo, sha="", path="", state="queued", reason=""):
    return {"repo": repo, "sha": sha[:12], "path": path, "state": state, "reason": reason,
            "run_id": None, "result": None, "needs_approval": False, "pr": None, "started": None}


def label(it):
    return it["repo"] + (f" ({it['path']})" if it["path"] else "")


def load(path):
    try:
        data = json.loads(path.read_text())
    except (OSError, ValueError):
        return None
    return data if isinstance(data, dict) else None


def save(queue, status):
    """Write the status atomically; the installation is done once no repo is queued or checking."""
    if status["state"] != "rejected":
        status["state"] = "checking" if any(i["state"] in OPEN for i in status["repos"]) else "done"
    status["updated"] = now()
    out = queue / "status"
    out.mkdir(parents=True, exist_ok=True)
    tmp = out / f".{status['installation_id']}.tmp"
    tmp.write_text(json.dumps(status, indent=2))
    os.replace(tmp, out / f"{status['installation_id']}.json")


def plan(repo, branch, token):
    """The queued entries for one public repo: a head SHA and one entry per project path."""
    r = call("GET", f"/repos/{repo}/branches/{branch}", token, ok_404=True)
    if r.status_code == 404:
        return [entry(repo, state="skipped", reason="empty repository")]
    full = r.json()["commit"]["sha"]
    tree = call("GET", f"/repos/{repo}/git/trees/{full}", token, params={"recursive": "1"}).json()["tree"]
    paths = choose_paths(tree)
    if not paths:
        return [entry(repo, full, state="skipped", reason="no package.json, foundry.toml or Cargo.toml")]
    return [entry(repo, full, p) for p in paths]


def intake(queue, request, installation_id):
    """Validate a request with the App and write its status. Raises GitHubError, leaving the
    request in place, when GitHub cannot answer."""
    jwt = make_jwt()
    r = call("GET", f"/app/installations/{installation_id}", jwt, ok_404=True)
    if r.status_code == 404:
        save(queue, {"installation_id": installation_id, "account": "", "state": "rejected",
                     "reason": "not an installation of Resurgo Agent", "repos": []})
        request.unlink(missing_ok=True)
        log(f"{installation_id} rejected")
        return
    account = r.json()["account"]["login"]
    token = call("POST", f"/app/installations/{installation_id}/access_tokens", jwt, json={
        "permissions": {"contents": "read", "metadata": "read"}}).json()["token"]
    repos = call("GET", "/installation/repositories", token, params={"per_page": 100}).json()["repositories"]
    entries, checked = [], 0
    for repo in repos:
        name = repo["full_name"]
        if repo["private"]:
            entries.append(entry(name, state="skipped", reason="private repositories come after the hackathon"))
        elif repo["archived"]:
            entries.append(entry(name, state="skipped", reason="archived"))
        elif checked >= MAX_REPOS:
            entries.append(entry(name, state="skipped",
                                 reason=f"only {MAX_REPOS} repositories are checked per installation"))
        else:
            checked += 1
            entries += plan(name, repo["default_branch"], token)
    save(queue, {"installation_id": installation_id, "account": account, "state": "checking",
                 "reason": "", "queued_at": now(), "repos": entries})
    request.unlink(missing_ok=True)
    log(f"{installation_id} {account} checking {sum(e['state'] == 'queued' for e in entries)} "
        f"of {len(entries)} repo paths")


def oldest_request(queue):
    found = []
    for f in (queue / "requests").glob("*.json"):
        if f.stem.isdigit():
            found.append(((load(f) or {}).get("received", ""), f.name, f))
    return min(found)[2] if found else None


def next_item(queue):
    """The first queued (or interrupted, still `checking`) entry of the lowest installation id."""
    files = [f for f in (queue / "status").glob("*.json") if f.stem.isdigit()]
    for f in sorted(files, key=lambda f: int(f.stem)):
        status = load(f)
        if status and status.get("state") == "checking":
            for it in status["repos"]:
                if it["state"] in OPEN:
                    return status, it
    return None


def sweep_running():
    """One build at a time on this host: a sweep counts as a build."""
    return subprocess.run(["pgrep", "-f", "--", r"-m resurgo\.sweep"], capture_output=True).returncode == 0


def note_waiting(queue):
    """Tell every installation with open work why nothing is moving: a sweep holds the host."""
    for f in (queue / "status").glob("*.json"):
        s = load(f)
        if s and s.get("state") == "checking" and not s.get("reason") \
                and any(i["state"] in OPEN for i in s["repos"]):
            s["reason"] = WAIT_REASON
            save(queue, s)


def open_pr(it, rec):
    """Open the PR for a passed run with a fix that needs no approval; the {url, number} or None."""
    run_dir = RUNS / it["run_id"]
    if (os.environ.get("RESURGO_AUTO_PR") != "1" or it["result"] not in ("runs", "runs_with_gaps")
            or it["needs_approval"] or not (run_dir / "fix.patch").exists()):
        return None
    if rec.get("pr"):
        return rec["pr"]
    p = subprocess.run([sys.executable, "-m", "resurgo.pr", str(run_dir)], capture_output=True,
                       text=True, timeout=600)
    if p.returncode:
        log(f"{it['run_id']} pr not opened: {scrub((p.stdout + p.stderr).strip()[-200:])}")
        return None
    return (load(run_dir / "result.json") or {}).get("pr")


def check(queue, status, it):
    """Reuse a recorded run or run one now. False when a sweep holds the host."""
    rec = find_record(RUNS, it["repo"], it["sha"], it["path"], __version__)
    if rec is None and sweep_running():
        note_waiting(queue)
        return False
    status["reason"] = ""
    if rec is None:
        it["state"] = "checking"
        it["started"] = now()
        save(queue, status)
        log(f"{status['installation_id']} {label(it)} checking")
        try:
            rec = run_one({"repo": it["repo"], "sha": it["sha"], "path": it["path"]},
                          {"agent_version": __version__, "set": "install",
                           "sweep_id": f"install-{status['installation_id']}"})
        except Exception as e:      # one repo never stops the worker
            rec = {"result": "error", "agent": {"detail": f"{type(e).__name__}: {e}"}}
    if rec["result"] == "error":
        it["reason"] = scrub((rec.get("agent") or {}).get("detail") or "run failed")[:200]
    else:
        it["run_id"] = rec.get("run_id")
        it["needs_approval"] = bool(rec.get("needs_approval"))
        it["result"] = rec["result"] if rec["result"] in RESULTS else "broken"
        if it["result"] != rec["result"]:
            it["reason"] = rec["result"].replace("_", " ")
        it["pr"] = open_pr(it, rec) if it["run_id"] else None
    it["state"] = "done"
    save(queue, status)
    log(f"{status['installation_id']} {label(it)} done result={it['result']}")
    return True


def requeue_stale(queue):
    """Weekly re-check: ask for a fresh request for a finished installation not updated for 7 days."""
    limit = datetime.now(timezone.utc) - RECHECK_AFTER
    for f in (queue / "status").glob("*.json"):
        s = load(f) or {}
        request = queue / "requests" / f.name
        if s.get("state") == "done" and datetime.fromisoformat(s["updated"]) < limit and not request.exists():
            request.parent.mkdir(parents=True, exist_ok=True)
            tmp = request.with_name(f".{f.stem}.worker.tmp")
            tmp.write_text(json.dumps({"installation_id": s["installation_id"], "received": now(),
                                       "setup_action": "update"}))
            os.replace(tmp, request)
            log(f"{f.stem} re-queued for the weekly re-check")
            return True
    return False


def step(queue):
    """One unit of work: take a request, else run one queued repo path, else re-queue a stale
    installation. True when something was done."""
    request = oldest_request(queue)
    if request:
        try:
            intake(queue, request, int(request.stem))
            return True
        except GitHubError as e:
            log(f"{request.stem} GitHub error, will retry: {e}")
    found = next_item(queue)
    if found:
        return check(queue, *found)
    return requeue_stale(queue)


def main(once=False):
    load_dotenv()
    if not os.environ.get("QUEUE_DIR"):
        sys.exit("QUEUE_DIR is not set")
    queue = Path(os.environ["QUEUE_DIR"])
    (queue / "requests").mkdir(parents=True, exist_ok=True)
    (queue / "status").mkdir(parents=True, exist_ok=True)
    while True:
        try:
            while step(queue):
                pass
        except Exception as e:      # keep the loop alive; the next pass retries
            log(f"error: {type(e).__name__}: {scrub(str(e))[:200]}")
        if once:
            return 0
        time.sleep(POLL_S)


if __name__ == "__main__":
    ap = argparse.ArgumentParser(prog="python -m resurgo.worker")
    ap.add_argument("--once", action="store_true", help="work until nothing is left, then exit")
    sys.exit(main(ap.parse_args().once))

"""Read-only public gallery API over the run records in RUNS_DIR, plus the built web app."""

import json
import logging
import os
import re
import time
from datetime import datetime, timezone
from pathlib import Path

from html import escape

from fastapi import FastAPI, HTTPException
from fastapi.responses import FileResponse, HTMLResponse, PlainTextResponse, RedirectResponse, Response

RUNS_DIR = Path(os.environ.get("RUNS_DIR", "")).resolve() if os.environ.get("RUNS_DIR") else None
DIST_DIR = Path(os.environ.get("WEB_DIST", Path(__file__).resolve().parent.parent / "web" / "dist")).resolve()

# 20261010T120139Z-5c3370f: UTC timestamp, then a short sha. Nothing else is ever a run id.
RUN_ID = re.compile(r"^[0-9]{8}T[0-9]{6}Z-[0-9a-f]{6,40}$")
# A run directory with no result.json younger than this is still being checked.
CHECKING_WINDOW_S = 45 * 60

app = FastAPI(title="Resurgo runs", docs_url=None, redoc_url=None, openapi_url=None)


def _runs_dir() -> Path:
    if RUNS_DIR is None or not RUNS_DIR.is_dir():
        raise HTTPException(503, "RUNS_DIR is not configured")
    return RUNS_DIR


def _run_dir(run_id: str) -> Path:
    if not RUN_ID.fullmatch(run_id):
        raise HTTPException(404, "no such run")
    root = _runs_dir()
    path = (root / run_id).resolve()
    if path.parent != root or not path.is_dir():
        raise HTTPException(404, "no such run")
    return path


_CACHE: dict[Path, tuple[int, dict | None]] = {}


def _load(run_dir: Path) -> dict | None:
    """result.json for a run, re-read only when the file changes."""
    path = run_dir / "result.json"
    try:
        mtime = path.stat().st_mtime_ns
    except OSError:
        return None
    hit = _CACHE.get(path)
    if hit and hit[0] == mtime:
        return hit[1]
    try:
        data = json.loads(path.read_text())
    except (OSError, ValueError):
        data = None
    _CACHE[path] = (mtime, data)
    return data


def _steps(side: dict | None) -> list[dict]:
    return [s for s in ((side or {}).get("steps") or []) if isinstance(s, dict)]


def _verified(result: dict) -> bool:
    """A run is verified when the separate clean container ran steps and it passed (flag, or every step exit 0)."""
    verifier = result.get("verifier") or {}
    steps = _steps(verifier)
    return bool(steps) and (verifier.get("passed") is True or all(s.get("exit_code") == 0 for s in steps))


_DIFF_HEADER = re.compile(r"^diff --git a/(.+?) b/(.+)$")
_TEST_KEY = re.compile(r"^\+\s*(?:no_)?match_\w+\s*=")
_TEST_SCRIPT = re.compile(r'^[+-]\s*"test"\s*:')
_TEST_FILE = re.compile(r"(^|/)(tests?|__tests__|spec)/|\.(test|spec)\.\w+$|_test\.\w+$|\.t\.sol$|(^|/)test_[^/]*$")


def _weakens_tests(patch: str | None) -> bool:
    """True when the patch makes tests pass by skipping them: an added match_*/no_match_* key in
    foundry.toml, a deleted test file, or a changed `test` script in package.json (the agent v2.1 rule)."""
    path = ""
    for line in (patch or "").splitlines():
        m = _DIFF_HEADER.match(line)
        if m:
            path = m.group(2)
            continue
        name = path.rsplit("/", 1)[-1]
        if line.startswith("deleted file mode") and _TEST_FILE.search(path):
            return True
        if name == "foundry.toml" and _TEST_KEY.match(line):
            return True
        if name == "package.json" and _TEST_SCRIPT.match(line):
            return True
    return False


def _status(result: dict, weakens_tests: bool = False) -> str:
    status = _judge(result)
    # A fix that only skipped tests is not a repair, whatever the clean container then said.
    return "fix_skipped_tests" if weakens_tests and status != "broken" else status


def _judge(result: dict) -> str:
    # runs | runs_with_gaps | broken are current. fixed | fail come from earlier agent versions,
    # which did write the verifier's steps: judge those by the steps, not by the old word.
    raw = str(result.get("result") or "unknown")
    # A code fix that passed in the clean container but waits for the owner: not a clean pass.
    if raw != "broken" and result.get("needs_approval") and _verified(result) and (result.get("verifier") or {}).get("passed") is not False:
        return "fix_awaiting_approval"
    if raw in ("runs", "runs_with_gaps", "broken"):
        return raw
    steps = _steps(result.get("verifier"))
    if steps:
        if _verified(result):
            gaps = result.get("gaps") or (result.get("verifier") or {}).get("gaps")
            return "runs_with_gaps" if gaps else "runs"
        return "broken"
    # No verifier steps: nothing was proved. "fixed" stays unverified; "fail" is broken.
    return "broken" if raw == "fail" else raw


def _fix_kind(result: dict, has_patch: bool) -> str | None:
    attempts = (result.get("agent") or {}).get("attempts") or []
    kinds = {a.get("kind") for a in attempts if a.get("status") in ("applied", "needs_approval")}
    if "code" in kinds:
        return "code"
    if "config" in kinds:
        return "config"
    if has_patch or (result.get("agent") or {}).get("rules_fired"):
        return "config"
    return None


_ANSI = re.compile(r"\x1b\[[0-9;]*m")
_ERROR_LINE = re.compile(r"error|ERR_|failed|timed out|fatal|exit code|cannot|not found", re.I)


def _tail(step: dict) -> list[str]:
    return [_ANSI.sub("", str(x)) for x in (step.get("output_tail") or []) if str(x).strip()]


def _error_line(result: dict) -> str | None:
    """The first error line of the first agent step that failed."""
    for s in _steps(result.get("agent")):
        if s.get("exit_code") != 0:
            lines = _tail(s)
            hit = next((l for l in lines if _ERROR_LINE.search(l)), None)
            return (hit or (lines[-1] if lines else None) or "")[:240] or None
    return None


def _problems(result: dict) -> list[dict]:
    """Causes of rot that the record itself evidences: {key, evidence}."""
    out: list[dict] = []
    lines = [l for s in _steps(result.get("agent")) for l in _tail(s)]
    hit = next((l for l in lines if "ERR_PNPM_IGNORED_BUILDS" in l), None)
    if hit:
        nxt = next((l for l in lines if "Ignored build scripts" in l), None)
        extra = re.sub(r"^[\s╰▶─×]+", "", nxt).strip() if nxt else None
        out.append({"key": "toolchain", "evidence": "\n".join(x for x in (hit, extra) if x)})
    for a in (result.get("agent") or {}).get("attempts") or []:
        why = a.get("rationale") or ""
        if re.search(r"better-sqlite3|native|V8|node-gyp", why, re.I):
            out.append({"key": "runtime", "evidence": why[:700]})
            break
    clock = next((l for l in lines if re.match(r"^timed out after \d+s", l)), None)
    if clock:
        out.append({"key": "clock", "evidence": clock})
    return out


def _brief(step: dict) -> dict:
    return {"name": step.get("name"), "ok": step.get("exit_code") == 0, "duration_s": step.get("duration_s")}


def _summary(run_id: str, result: dict, patch: str | None) -> dict:
    started, ended = result.get("started"), result.get("ended")
    agent = result.get("agent") or {}
    verifier = result.get("verifier") or {}
    calls = result.get("model_calls") or []
    model_s = sum(c.get("duration_s") or 0 for c in calls)
    patch_lines = patch.splitlines() if patch else []
    weakens = _weakens_tests(patch)
    return {
        "id": run_id,
        "repo": result.get("repo"),
        "sha": result.get("sha"),
        "path": result.get("path") or "",
        "type": result.get("type"),
        "status": _status(result, weakens),
        "set": result.get("set"),
        "agent_version": result.get("agent_version"),
        "sweep_id": result.get("sweep_id"),
        "weakens_tests": weakens,
        "duration_s": round(ended - started, 1) if isinstance(started, (int, float)) and isinstance(ended, (int, float)) else None,
        "model_calls": len(calls),
        "fix_kind": _fix_kind(result, bool(patch)),
        "needs_approval": bool(result.get("needs_approval")),
        "started": started,
        # What the landing page draws from, so it does not fetch every run's record.
        "verified": _verified(result),
        "gaps": result.get("gaps") or verifier.get("gaps") or [],
        "agent_steps": [_brief(s) for s in _steps(agent)],
        "verifier_steps": [_brief(s) for s in _steps(verifier)],
        "attempts": [
            {
                "kind": a.get("kind"),
                "files": a.get("files") or [],
                "result": a.get("result"),
                "status": a.get("status"),
                "confidence": a.get("confidence"),
                "rationale": (a.get("rationale") or "")[:700] or None,
            }
            for a in (agent.get("attempts") or [])
        ],
        "rules_fired": agent.get("rules_fired") or [],
        "model": next((c.get("model") for c in calls if c.get("model")), None),
        "model_seconds": round(model_s, 1) if calls else None,
        "error_line": _error_line(result),
        "problems": _problems(result),
        "patch_preview": "\n".join(patch_lines[:14]) if patch else None,
        "patch_added": sum(1 for l in patch_lines if l.startswith("+") and not l.startswith("+++")),
    }


def _checking_row(entry: Path) -> dict:
    return {"id": entry.name, "repo": None, "sha": None, "path": "", "type": None, "status": "checking",
            "set": None, "agent_version": None, "sweep_id": None, "weakens_tests": False,
            "duration_s": None, "model_calls": 0, "fix_kind": None, "needs_approval": False,
            "started": entry.stat().st_mtime, "verified": False, "gaps": [], "agent_steps": [],
            "verifier_steps": [], "attempts": [], "rules_fired": [], "model": None, "model_seconds": None,
            "error_line": None, "problems": [], "patch_preview": None, "patch_added": 0}


def _rows() -> list[dict]:
    root = _runs_dir()
    now = time.time()
    rows = []
    for entry in root.iterdir():
        if not RUN_ID.fullmatch(entry.name) or not entry.is_dir() or entry.resolve().parent != root:
            continue
        result = _load(entry)
        if result is not None:
            try:
                patch = (entry / "fix.patch").read_text()
            except OSError:
                patch = None
            rows.append(_summary(entry.name, result, patch))
        elif now - entry.stat().st_mtime < CHECKING_WINDOW_S:
            rows.append(_checking_row(entry))
    rows.sort(key=lambda r: r["id"], reverse=True)
    return rows


@app.get("/api/runs")
def list_runs() -> list[dict]:
    return _rows()


@app.get("/api/runs/{run_id}")
def get_run(run_id: str) -> dict:
    run_dir = _run_dir(run_id)
    result = _load(run_dir)
    if result is None:
        raise HTTPException(404, "this run has no record yet")
    patch = None
    try:
        patch = (run_dir / "fix.patch").read_text()
    except OSError:
        pass
    return {"summary": _summary(run_id, result, patch), "result": result, "fix_patch": patch}


# Agent view: the same facts as the site, in plain text. Paths are relative on purpose.
_STATUS_WORD = {
    "runs": "Runs",
    "runs_with_gaps": "Runs with gaps",
    "fix_awaiting_approval": "Fix verified · awaiting approval",
    "fix_skipped_tests": "Fix skipped tests · not a repair",
    "broken": "Broken",
    "fixed": "Fixed, unverified",
}

_HOW = """## How a run is proved

1. **Fresh clone.** The agent container clones the repository at a pinned commit, picks the package manager from the lockfile, and runs install, build, test and start in order, stopping at the first failure.
2. **Diagnose.** Deterministic rules run first. A model is called only when a step failed; it proposes the least invasive fix (configuration before source code).
3. **Repair.** The fix is applied as a patch and the failed step is run again. A source-code change is marked `needs_approval`: older agent versions only proposed it, newer ones apply it inside the sandbox to test it, and in both cases it reaches your repository only after you approve.
4. **Prove.** A second, separate container clones the same commit, applies only the fix and reruns every step. Its steps are recorded as `verifier.steps`. The agent that wrote the fix cannot write to it.

## Status vocabulary

- `runs` (✓ Runs): the verifier ran and every step passed.
- `runs_with_gaps` (◐ Runs with gaps): the verifier passed, and the record lists `gaps` (things it could not exercise, such as a missing test script).
- `fix_awaiting_approval` (◆ Fix verified · awaiting approval): the fix passed in the clean container and changes source code, so it waits for the owner's approval. The repository itself does not run clean yet; `verified` is true because the verifier passed.
- `fix_skipped_tests` (✗ Fix skipped tests · not a repair): the patch only excluded tests (a `match_*` or `no_match_*` key added to `foundry.toml`, a deleted test file, or a changed `test` script in `package.json`). It is not counted as a repair and is never featured. `weakens_tests` is true.
- `broken` (✗ Broken): a step failed and no verified fix exists.
- `checking` (◌ Checking): the run has started and has no record yet.
- `fixed` (◐ Fixed, unverified): only in records from an earlier agent version that have no verifier steps at all.

A run counts as verified only when `verified` is true: the verifier has at least one step and all steps exited 0. Nothing is claimed beyond the recorded steps; for example a verifier that only ran `install` has proved the install, not the build.
"""

_API = """## API (read-only, JSON)

- `GET /api/runs`: every run, newest first. Each item carries `id`, `repo`, `sha`, `path`, `type`, `status`, `set` (`heldout`, `dev` or null), `agent_version`, `sweep_id`, `weakens_tests`, `verified`, `duration_s`, `model_calls`, `fix_kind` (`config`, `code` or null), `needs_approval`, `gaps`, `agent_steps` and `verifier_steps` (`name`, `ok`, `duration_s`), `attempts` (`kind`, `files`, `result`, `status`, `confidence`, `rationale`), `error_line`, `problems`, `patch_preview`.
- `GET /api/runs/{id}`: one run as `{summary, result, fix_patch}`. `result` is the full record: steps with commands, exit codes, durations and output tails, model calls, and attempts. `fix_patch` is a unified diff or null.
- Run ids look like `20261010T120139Z-5c3370f` (UTC start time, then the short commit).

## Pages

- `/`: the landing page. `/runs`: the gallery. `/runs/{id}`: one run with a replay and its fix diff.
- `/index.md` and `/llms.txt`: this description.
"""


def _agent_view(short: bool) -> str:
    head = (
        "# Resurgo\n\n"
        "> Resurgo fresh-clones a repository, repairs what rotted, and proves the fix in a separate clean container.\n\n"
        "Current state: a hackathon build. The GitHub App \"Resurgo Agent\" is installed on the repositories you pick. "
        "It opens a pull request only for a fix that passed in a clean container, and a change to source code waits "
        "for your approval. The runs below are recorded runs on public repositories. "
        "There are no customers, testimonials or benchmark claims on this site.\n\n"
    )
    live = ""
    try:
        latest: dict[tuple, dict] = {}
        for r in _rows():
            if r["repo"] and r["status"] != "checking":
                latest.setdefault((r["repo"], r["path"]), r)
        if latest:
            live = "## Latest run per repository\n\n" + "\n".join(
                f"- [{r['repo']}{'/' + r['path'] if r['path'] else ''}](/runs/{r['id']}): "
                f"{_STATUS_WORD.get(r['status'], r['status'])}"
                f"{', verified' if r['verified'] and r['status'] not in ('fix_awaiting_approval', 'fix_skipped_tests') else ''}"
                f"{', fix: ' + r['fix_kind'] if r['fix_kind'] else ''}"
                for r in latest.values()
            ) + "\n\n"
    except HTTPException:
        pass  # RUNS_DIR not configured: describe the system without a live list
    if short:
        return head + live + "## Links\n\n- [Full description](/index.md)\n- [Run list as JSON](/api/runs)\n"
    return head + live + _API + "\n" + _HOW


@app.get("/index.md", include_in_schema=False)
def agent_view_md() -> PlainTextResponse:
    return PlainTextResponse(_agent_view(short=False), media_type="text/markdown; charset=utf-8")


@app.get("/llms.txt", include_in_schema=False)
def agent_view_llms() -> PlainTextResponse:
    return PlainTextResponse(_agent_view(short=True), media_type="text/plain; charset=utf-8")


# GitHub App installs. The API only drops a request file into QUEUE_DIR/requests/ and reads
# QUEUE_DIR/status/; a separate worker on the host runs the checks and writes the status files.
INSTALLATION_ID = re.compile(r"[0-9]{1,12}")
QUEUE_LIMIT = 50


def _queue_dir() -> Path | None:
    value = os.environ.get("QUEUE_DIR")
    return Path(value) if value else None


class _HideOAuthCode(logging.Filter):
    """The callback URL carries GitHub's one-time `code`; keep it out of uvicorn's access log."""

    def filter(self, record: logging.LogRecord) -> bool:
        if isinstance(record.args, tuple) and len(record.args) > 2 and isinstance(record.args[2], str):
            record.args = (*record.args[:2], re.sub(r"code=[^&\s]*", "code=-", record.args[2]), *record.args[3:])
        return True


logging.getLogger("uvicorn.access").addFilter(_HideOAuthCode())


def _enqueue(queue: Path, installation_id: str, setup_action: str) -> bool:
    """Write requests/<id>.json atomically, never over an existing file. False when the queue is full."""
    requests = queue / "requests"
    requests.mkdir(parents=True, exist_ok=True)
    final = requests / f"{installation_id}.json"
    if final.exists():
        return True
    if sum(1 for p in requests.iterdir() if p.suffix == ".json") >= QUEUE_LIMIT:
        return False
    body = {
        "installation_id": int(installation_id),
        "received": datetime.now(timezone.utc).isoformat(timespec="seconds"),
        "setup_action": setup_action,
    }
    tmp = requests / f".{installation_id}.{os.getpid()}.tmp"
    tmp.write_text(json.dumps(body))
    try:
        os.link(tmp, final)  # fails if the file appeared meanwhile; it is left alone
    except FileExistsError:
        pass
    finally:
        tmp.unlink(missing_ok=True)
    return True


@app.get("/auth/github/callback", include_in_schema=False)
def github_callback(installation_id: str = "", setup_action: str = "install") -> RedirectResponse:
    # `code` is deliberately not a parameter: it is never read, stored or logged.
    if not INSTALLATION_ID.fullmatch(installation_id):
        return RedirectResponse("/", status_code=303)
    target = f"/installed/{installation_id}"
    queue = _queue_dir()
    if queue is not None:
        try:
            if not _enqueue(queue, installation_id, "update" if setup_action == "update" else "install"):
                target += "?queue=full"
        except OSError:
            pass  # the page then reads "waiting"; nothing was recorded
    return RedirectResponse(target, status_code=303)


@app.get("/api/installations/{installation_id}")
def get_installation(installation_id: str) -> dict:
    queue = _queue_dir()
    if queue is None or not INSTALLATION_ID.fullmatch(installation_id):
        raise HTTPException(404, "no such installation")
    try:
        data = json.loads((queue / "status" / f"{installation_id}.json").read_text())
        if isinstance(data, dict):
            return data
    except (OSError, ValueError):
        pass
    if (queue / "requests" / f"{installation_id}.json").is_file():
        return {"installation_id": int(installation_id), "state": "received"}
    raise HTTPException(404, "no such installation")


SITE_URL = os.environ.get("SITE_URL", "https://resurgo.timidan.xyz").rstrip("/")


@app.get("/robots.txt", include_in_schema=False)
def robots() -> PlainTextResponse:
    body = f"User-agent: *\nAllow: /\nDisallow: /installed/\nDisallow: /auth/\n\nSitemap: {SITE_URL}/sitemap.xml\n"
    return PlainTextResponse(body, media_type="text/plain; charset=utf-8")


@app.get("/sitemap.xml", include_in_schema=False)
def sitemap() -> Response:
    urls = "".join(f"<url><loc>{SITE_URL}{p}</loc></url>" for p in ("/", "/runs", "/data"))
    body = f'<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">{urls}</urlset>\n'
    return Response(body, media_type="application/xml")


# Per-run share cards: the SPA's index.html with this run's title and description swapped in.
_TITLE_TAG = re.compile(r"<title>.*?</title>", re.S)


def _run_card(run_id: str) -> tuple[str, str] | None:
    """(title, description) for a recorded run, or None when there is no such record."""
    try:
        result = _load(_run_dir(run_id))
    except HTTPException:
        return None
    if not result or not result.get("repo"):
        return None
    try:
        patch = (_run_dir(run_id) / "fix.patch").read_text()
    except (OSError, HTTPException):
        patch = None
    status = _status(result, _weakens_tests(patch))
    word = _STATUS_WORD.get(status, status)
    n = len((result.get("agent") or {}).get("attempts") or [])
    tried = f"{n} repair attempt{'' if n == 1 else 's'}" if n else "no repair attempted"
    if status == "fix_skipped_tests":
        proof = "tests were skipped, not repaired"
    elif _verified(result) and status != "fix_awaiting_approval":
        proof = "verified in a clean container"
    elif status == "fix_awaiting_approval":
        proof = "passed in a clean container, awaiting approval"
    else:
        proof = "not verified"
    desc = f"{result['repo']}: {word}. {tried.capitalize()}, {proof}. A recorded Resurgo run you can replay."
    return f"{result['repo']} · {word} · Resurgo", desc if len(desc) <= 160 else desc[:159].rstrip() + "…"


def _with_card(html: str, title: str, desc: str, run_id: str) -> str:
    t, d, u = escape(title, quote=True), escape(desc, quote=True), escape(f"{SITE_URL}/runs/{run_id}", quote=True)
    html = _TITLE_TAG.sub(lambda _: f"<title>{t}</title>", html, count=1)
    for key, value in (("name", "description"), ("property", "og:title"), ("property", "og:description"),
                       ("property", "og:url"), ("name", "twitter:title"), ("name", "twitter:description")):
        v = {"og:title": t, "twitter:title": t, "og:url": u}.get(value, d)
        html = re.sub(
            rf'(<meta\s+{key}="{re.escape(value)}"\s+content=")[^"]*(")',
            lambda m: m.group(1) + v + m.group(2), html, count=1,
        )
    return html


# The built web app, with SPA fallback. Never serve outside DIST_DIR.
@app.get("/{rest:path}", include_in_schema=False)
def web(rest: str):
    if rest.startswith("api/"):
        raise HTTPException(404)
    candidate = (DIST_DIR / rest).resolve()
    if rest and candidate.is_file() and DIST_DIR in candidate.parents:
        return FileResponse(candidate)
    index = DIST_DIR / "index.html"
    if not index.is_file():
        raise HTTPException(404, "web app is not built")
    run_id = rest[len("runs/"):] if rest.startswith("runs/") else ""
    card = _run_card(run_id) if RUN_ID.fullmatch(run_id) and RUNS_DIR is not None else None
    if card:
        return HTMLResponse(_with_card(index.read_text(), *card, run_id))
    return FileResponse(index)

