  weakens_tests?: boolean;
  verified?: boolean;
  gaps?: string[];
  agent_steps?: StepBrief[];
  verifier_steps?: StepBrief[];
  attempts?: AttemptBrief[];
  rules_fired?: string[];
  model?: string | null;
  model_seconds?: number | null;
  error_line?: string | null;
  problems?: { key: string; evidence: string }[];
  patch_preview?: string | null;
  patch_added?: number;
};

export type RunDetail = { summary: RunSummary; result: RunResult; fix_patch: string | null };

type Async<T> = { data: T | null; error: string | null; loading: boolean };

function useFetch<T>(url: string | null): Async<T> {
  const [state, setState] = useState<Async<T>>({ data: null, error: null, loading: url !== null });
  r.set === "heldout" ? `heldout:${r.agent_version ?? ""}` : r.set === "dev" ? "dev" : r.set === "install" ? "install" : null;

const versionWord = (v: string) => (/^v\d+(\.\d+)?$/.test(v) ? v : "early build");

const STATUS_CHIPS: { key: string; label: string; test: (s: string) => boolean }[] = [
  { key: "runs", label: "Verified", test: (s) => s === "runs" },
  { key: "broken", label: "Broken", test: (s) => s === "broken" || s === "fail" },
  { key: "gaps", label: "Gaps", test: (s) => s === "runs_with_gaps" },
  { key: "approval", label: "Awaiting approval", test: (s) => s === "fix_awaiting_approval" },
  { key: "skipped", label: "Skipped tests", test: (s) => s === "fix_skipped_tests" },
];

function Chip({ on, onClick, children }: { on: boolean; onClick: () => void; children: string }) {
  return (
    <button
      type="button"
      aria-pressed={on}
      onClick={onClick}
