        "press chip-t rounded-full border px-3 py-1 text-sm font-semibold pointer-coarse:min-h-11",
        on ? "border-accent-strong bg-panel text-foreground" : "border-control text-muted-foreground hover:bg-muted hover:text-foreground",
        patchLast({ ok, lines, flash: !ok });
        // Reading pause: long enough for the error lines, then the next beat.
        await sleep(ok ? 160 : readingMs(lines.join(" ")));
      }
    }
    if (!live()) return;
    setState("done");
    if (s.verified && s.status !== "fix_awaiting_approval" && s.status !== "fix_skipped_tests") lift(); // the lifted-r wordmark rises once the replay verifies clean
